# ------------------------------------------------------------------------------------------
# formatting (one style everywhere, so the number check can compare like with like)
# ------------------------------------------------------------------------------------------
def chf(v) -> str:
    return f"CHF {v:,.0f}"


def num(v, d: int = 0) -> str:
    return f"{v:,.{d}f}"


def kg(v) -> str:
    return f"{v:,.0f} kg CO2"


def kwh(v) -> str:
    return f"{v:,.0f} kWh"


def pct(v, d: int = 1) -> str:
    return f"{v * 100:.{d}f} %"


