def _fact(fid, section, text, source, kind="derived", keys=(), corpus="ledger", title=None):
    return {"id": fid, "section": section, "title": title or fid, "text": " ".join(text.split()), "source": source,
            "kind": kind, "keys": sorted({k.lower() for k in keys if k}), "corpus": corpus}


