# 1. ledger facts (from app_data.json, numbers by code)
# ------------------------------------------------------------------------------------------
def _co2_triplet(r, mix="consumption"):
    return (f"{kg(r[f'co2_mid_{mix}'])} ({VIEW}; range {num(r[f'co2_low_{mix}'])}-{num(r[f'co2_high_{mix}'])} kg "
            f"with low/high factors)")


def _footprint(r) -> str:
    return (f"{chf(r['cost_chf'])} per year, {kwh(r['kwh_mid'])}, {_co2_triplet(r)}; production mix "
            f"{num(r['co2_mid_production'])} kg; market-based {num(r['co2_mid_market'])} kg")


METRIC_KEYS = ["cost_chf", "quantity", *[f"kwh_{x}" for x in ("low", "mid", "high")],
               *[f"co2_{x}_{m}" for x in ("low", "mid", "high") for m in ("consumption", "production", "market")]]


def resources(d: dict) -> list[dict]:
    """One entry per resource and source (AI and SaaS rows are split by department in by_resource: summed here,
    with the split kept as 'parts')."""
    out: dict[tuple, dict] = {}
    for r in d["by_resource"]:
        k = (r["resource_id"], r["source"])
        if k not in out:
            out[k] = {**r, "tool": r["tool"] or r["resource_id"], "parts": [],
                      "fid": f"res-{r['resource_id']}-{r['source']}", **{m: 0.0 for m in METRIC_KEYS}}
        e = out[k]
        for m in METRIC_KEYS:
            e[m] += r.get(m) or 0.0
        if e["unit"] != r["unit"]:
            e["unit"] = "mixed"
        e["parts"].append({"department": r["department"] or "shared", "cost_chf": r["cost_chf"]})
    return sorted(out.values(), key=lambda x: -x["cost_chf"])


