REF_DOCS = {   # file -> (label, licence)
    "ghg_protocol_scope2_guidance.pdf": ("GHG Protocol Scope 2 Guidance (WRI/WBCSD 2015)", "free download, ghgprotocol.org"),
    "focus_spec_v1_4.pdf": ("FinOps FOCUS specification v1.4", "CC BY 4.0"),
    "ccf_methodology.md": ("Cloud Carbon Footprint methodology", "Apache 2.0"),
}
EMBER = ("ember_yearly_countries.csv", "ember_yearly_global.csv")
MAX_CHARS = 900


def _sha(p: Path) -> str:
    return hashlib.sha1(p.read_bytes()).hexdigest()[:16]


def _pack(paras: list[str], limit: int = MAX_CHARS) -> list[str]:
    out, cur = [], ""
    for p in paras:
        p = " ".join(p.split())
        if not p:
            continue
        while len(p) > limit:               # very long paragraph: cut at a sentence end
            cut = p.rfind(". ", 0, limit) + 1 or limit
            out.append((cur + " " + p[:cut]).strip()) if cur else out.append(p[:cut].strip())
            cur, p = "", p[cut:].strip()
        if len(cur) + len(p) + 1 > limit and cur:
            out.append(cur)
            cur = p
        else:
            cur = f"{cur} {p}".strip()
    if cur:
        out.append(cur)
    return out


def _good(text: str) -> bool:
    letters = sum(ch.isalpha() for ch in text)
    return (len(text) >= 250 and letters / max(len(text), 1) > 0.6 and text.count("....") < 3
            and text.count(". .") < 3)


def _md_chunks(p: Path, label: str, lic: str) -> list[dict]:
    txt = p.read_text(encoding="utf-8")
    txt = re.sub(r"^---.*?---\s*", "", txt, flags=re.S)                      # front matter
    txt = re.sub(r"\[([^\]]+)\]\([^)]+\)", r"\1", txt)                       # links -> link text
    out, head = [], "Introduction"
    for sec in re.split(r"\n(?=#{1,4} )", txt):
        m = re.match(r"#{1,4} (.+)", sec)
        if m:
            head = m.group(1).strip()
            sec = sec[m.end():]
        body = re.sub(r"\|", " ", sec)
        for i, c in enumerate(_pack(re.split(r"\n\s*\n", body))):
            if _good(c):
                out.append(_fact(f"ref-ccf-{len(out)}", "reference", f"{head}: {c}", f"{label} ({lic}), section '{head}'",
                                 "read", corpus="reference", title=f"{label}: {head}"))
    return out


def _pdf_chunks(p: Path, label: str, lic: str, short: str) -> list[dict]:
    from pypdf import PdfReader                                               # optional (finetune group)
    out = []
    for no, page in enumerate(PdfReader(str(p)).pages, 1):
        try:
            txt = page.extract_text() or ""
        except Exception:                                                     # damaged page: skip, keep the rest
            continue
        txt = re.sub(r"-\n(?=[a-z])", "", txt)                               # re-join hyphenated words
        for c in _pack(re.split(r"\n\s*\n|(?<=[.:;])\n", txt)):
            if _good(c):
                out.append(_fact(f"ref-{short}-{len(out)}", "reference", c, f"{label} ({lic}), p. {no}", "read",
                                 corpus="reference", title=f"{label}, p. {no}"))
    return out


def _ember_chunks(files: list[Path]) -> list[dict]:
    import pandas as pd
    frames = [pd.read_csv(f, encoding="utf-8") for f in files]
    e = pd.concat(frames, ignore_index=True).drop_duplicates(["Area", "Year", "Electricity source"])
    col = "Emissions intensity (gCO2e/kWh)"
    ours = {"Switzerland": [F.GRID["CH_production"], F.GRID["CH_consumption"]], "Germany": [F.GRID["DE"]],
            "Ireland": [F.GRID["IE"]], "EU": [F.GRID["EU"]]}
    out = []
    for area, facs in ours.items():
        a = e[(e.Area == area) & (e["Electricity source"].str.lower() == "total generation")].sort_values("Year")
        if a.empty or a[col].isna().all():
            continue
        last = a[a[col].notna()].tail(4)
        imp = e[(e.Area == area) & (e["Electricity source"] == "Net imports")].set_index("Year")["Generation (TWh)"]
        yrs = "; ".join(f"{int(y)}: {v:.0f} g" for y, v in zip(last.Year, last[col]))
        y_last = int(last.Year.iloc[-1])
        imp_txt = (f" Net imports {y_last}: {imp.get(y_last):.1f} TWh." if y_last in imp.index and
                   pd.notna(imp.get(y_last)) else "")
        cmp_txt = "; ".join(f"{f.key} = {f.mid * 1000:.0f} g (range {f.low * 1000:.0f}-{f.high * 1000:.0f} g)"
                            for f in facs)
        out.append(_fact(f"ref-ember-{area}", "reference", f"Ember yearly electricity data, {area}: CO2 intensity of "
                         f"electricity GENERATION (production basis, imports not counted) {yrs} CO2e per kWh.{imp_txt} "
                         f"GreenLedger factors for comparison: {cmp_txt}. A consumption mix that includes imports can "
                         f"be higher than the generation intensity.", "Ember yearly electricity data (CC BY 4.0), "
                         "ember-energy.org", "read", [area, "ember", "grid"], corpus="reference",
                         title=f"Ember grid intensity {area}"))
    return out


def reference_facts(log: list | None = None) -> list[dict]:
    """Chunks of the methodology documents. Cached by file hash, so a machine without pypdf reuses the cache."""
    from .limits import _INJ
    cache = json.loads(REF_CACHE.read_text(encoding="utf-8")) if REF_CACHE.exists() else {}
    new, out = {}, []
    jobs = [(n, lab, lic) for n, (lab, lic) in REF_DOCS.items()] + [("ember", None, None)]
    for name, label, lic in jobs:
        paths = [REFERENCE / f for f in EMBER] if name == "ember" else [REFERENCE / name]
        paths = [p for p in paths if p.exists()]
        if not paths:
            # Originals are not in git (size, copyright): reuse the committed extract so the index is identical on
            # every machine. Drop them in data/raw/external/reference/ to re-extract.
            if name in cache:
                new[name] = cache[name]
                out += [c for c in cache[name]["chunks"] if not _INJ.search(c["text"])]
            continue
        sig = "+".join(_sha(p) for p in paths)
        if name in cache and cache[name]["sha"] == sig:
            chunks = cache[name]["chunks"]
        else:
            try:
                if name == "ember":
                    chunks = _ember_chunks(paths)
                elif name.endswith(".md"):
                    chunks = _md_chunks(paths[0], label, lic)
                else:
                    chunks = _pdf_chunks(paths[0], label, lic, name.split("_")[0])
            except ImportError:
                if log is not None:
                    log.append(f"{name}: skipped (install `uv sync --group finetune` for PDF support)")
                continue
        new[name] = {"sha": sig, "chunks": chunks}
        kept = [c for c in chunks if not _INJ.search(c["text"])]
        if log is not None and len(kept) < len(chunks):
            log.append(f"{name}: {len(chunks) - len(kept)} chunk(s) with instruction-like text dropped")
        out += kept
    if new != cache:
        REF_CACHE.write_text(json.dumps(new, ensure_ascii=False), encoding="utf-8")
    return out


# ------------------------------------------------------------------------------------------
# 3. index (chunks + optional dense vectors)
# ------------------------------------------------------------------------------------------
def _text_key(c: dict) -> str:
    return hashlib.sha1((c["title"] + "\n" + c["text"]).encode("utf-8")).hexdigest()[:20]


def dense_available() -> bool:
    from importlib.util import find_spec
    return find_spec("sentence_transformers") is not None


_EMBEDDER = None


def embedder():
    global _EMBEDDER
    if _EMBEDDER is None:
        import os
        os.environ.setdefault("HF_HUB_OFFLINE", "1")        # offline first: use the cached model, never the network
        from sentence_transformers import SentenceTransformer
        _EMBEDDER = SentenceTransformer(embed_model())
    return _EMBEDDER


def build_index(data: dict) -> dict:
    """Write rag_chunks.json (+ rag_index.npz with embeddings). Called by export.build_all(), so the index always
    matches the numbers on screen. Embeddings are recomputed only for chunks whose text changed."""
    log: list[str] = []
    chunks = ledger_facts(data) + reference_facts(log)
    keys = [_text_key(c) for c in chunks]
    PROCESSED.mkdir(parents=True, exist_ok=True)
    CHUNKS.write_text(json.dumps({"chunks": chunks, "log": log}, ensure_ascii=False), encoding="utf-8")
    old = {}
    if VECTORS.exists():
        with np.load(VECTORS, allow_pickle=False) as z:       # closes the file (Windows keeps open .npz files locked)
            if str(z["model"]) == embed_model():
                old = dict(zip(z["keys"].tolist(), z["vecs"]))
    missing = [i for i, k in enumerate(keys) if k not in old]
    dense = False
    if not missing or dense_available():
        try:
            if missing:
                vec = embedder().encode([chunks[i]["title"] + ". " + chunks[i]["text"] for i in missing],
                                        batch_size=64, normalize_embeddings=True, show_progress_bar=False)
                old.update({keys[i]: v for i, v in zip(missing, vec)})
            mat = np.stack([old[k] for k in keys]).astype(np.float32)
            np.savez_compressed(VECTORS, keys=np.array(keys), vecs=mat, model=np.array(embed_model()))
            dense = True
        except Exception as e:                       # e.g. model not downloaded: BM25 only, never break the build
            log.append(f"dense embeddings skipped: {type(e).__name__}: {str(e)[:120]}")
    # Without the optional group the vectors stay as a cache: Retriever uses them only if every chunk key matches.
    n_ref = sum(c["corpus"] == "reference" for c in chunks)
    return {"chunks": len(chunks), "ledger": len(chunks) - n_ref, "reference": n_ref, "dense": dense,
            "embed_model": embed_model() if dense else None, "log": log}


# ------------------------------------------------------------------------------------------
# 4. retrieval: exact IDs + BM25 + dense, reciprocal rank fusion
# ------------------------------------------------------------------------------------------
STOP = set("a an the of to in on for and or is are was be by with what which who how much many does do did it its "
           "this that from as at per our we us you your me i can could should would will there their them about "
           "der die das und oder ist sind was wie viel viele wer welche welcher mit von für fur im in auf zu den dem "
           "des ein eine einen kostet".split())
_TOK = re.compile(r"[a-z0-9äöüß]+(?:[-_.][a-z0-9äöüß]+)*")
ID_RE = re.compile(r"\b(?:[mbxwqc]\d{1,2}|t-\d{4}|f-[a-z0-9-]+|inj-t-\d{4})\b", re.I)


def tokens(text: str) -> list[str]:
    out = []
    for t in _TOK.findall(text.lower()):
        if t in STOP:
            continue
        out.append(t)
        if "-" in t or "_" in t:
            out += [p for p in re.split(r"[-_]", t) if p and p not in STOP and not p.isdigit()]
    return out


class Retriever:
    def __init__(self, chunks: list[dict] | None = None, vectors: np.ndarray | None = None, use_dense: bool = True):
        if chunks is None:
            chunks = json.loads(CHUNKS.read_text(encoding="utf-8"))["chunks"]
            if use_dense and VECTORS.exists():
                with np.load(VECTORS, allow_pickle=False) as z:
                    pos = {k: i for i, k in enumerate(z["keys"].tolist())}
                    ks = [_text_key(c) for c in chunks]
                    if all(k in pos for k in ks):
                        vectors = z["vecs"][[pos[k] for k in ks]]
        self.chunks = chunks
        self.vectors = vectors if (use_dense and vectors is not None and dense_available()) else None
        docs = [tokens(c["title"] + " " + c["text"] + " " + " ".join(c["keys"])) for c in chunks]
        self.tf = [Counter(d) for d in docs]
        self.len = np.array([len(d) for d in docs], dtype=float)
        df = Counter(t for d in docs for t in set(d))
        n = len(docs)
        self.idf = {t: math.log(1 + (n - f + 0.5) / (f + 0.5)) for t, f in df.items()}
        self.avg = float(self.len.mean()) if n else 1.0
        self.keymap: dict[str, list[int]] = {}
        for i, c in enumerate(chunks):
            for k in c["keys"]:
                self.keymap.setdefault(k, []).append(i)

    def bm25(self, q: str) -> np.ndarray:
        s = np.zeros(len(self.chunks))
        k1, b = 1.4, 0.75
        for t in set(tokens(q)):
            idf = self.idf.get(t)
            if idf is None:
                continue
            for i, tf in enumerate(self.tf):
                f = tf.get(t)
                if f:
                    s[i] += idf * f * (k1 + 1) / (f + k1 * (1 - b + b * self.len[i] / self.avg))
        return s

    def exact(self, q: str) -> list[int]:
        """Chunks whose ID / resource / department / contract is named in the question."""
        ql = q.lower()
        hits = []
        for k, idx in self.keymap.items():
            if len(k) < 3 and not ID_RE.fullmatch(k):
                continue
            if ID_RE.fullmatch(k):
                ok = re.search(rf"(?<![\w-]){re.escape(k)}(?![\w-])", ql) is not None
            else:
                ok = re.search(rf"(?<![\w-]){re.escape(k)}(?![\w])", ql) is not None
            if ok:
                hits += idx
        return list(dict.fromkeys(hits))

    def search(self, q: str, k: int = 6, max_reference: int = 2) -> list[dict]:
        bm = self.bm25(q)
        ranks = [np.argsort(-bm)]
        if self.vectors is not None:
            qv = embedder().encode([q], normalize_embeddings=True, show_progress_bar=False)[0]
            ranks.append(np.argsort(-(self.vectors @ qv)))
        fused = np.zeros(len(self.chunks))
        for r in ranks:
            fused[r] += 1.0 / (60 + np.arange(1, len(r) + 1))
        fused[bm == 0] *= 0.5 if self.vectors is not None else 0.0          # no shared word at all: weaker signal
        ledger_boost = np.array([1.15 if c["corpus"] == "ledger" else 1.0 for c in self.chunks])
        order = list(np.argsort(-(fused * ledger_boost)))
        ex = self.exact(q)
        ql = q.lower()
        # the fact whose own ID is named (M4) before facts that merely mention it (M4-how, rule-M4)
        ex.sort(key=lambda i: (re.search(rf"(?<![\w-]){re.escape(self.chunks[i]['id'].lower())}(?![\w-])", ql) is None,
                               -fused[i]))
        picked, n_ref = [], 0
        for i in [*ex[:k], *order]:
            if i in picked or (fused[i] <= 0 and i not in ex):
                continue
            if self.chunks[i]["corpus"] == "reference":
                if n_ref >= max_reference:
                    continue
                n_ref += 1
            picked.append(i)
            if len(picked) >= k:
                break
        return [{**self.chunks[i], "score": float(fused[i]), "exact": i in ex} for i in picked]


def context_block(facts: list[dict]) -> str:
    lines = []
    for n, f in enumerate(facts, 1):
        tag = "reference document, not company data" if f["corpus"] == "reference" else f"{f['kind']}"
        lines.append(f"[{n}] ({tag}; source: {f['source']}) {f['text']}")
    return "\n".join(lines)


# ------------------------------------------------------------------------------------------
# 5. guard + number check
# ------------------------------------------------------------------------------------------
# Same patterns as limits.INJECTION_PATTERNS plus the app's chat regex (INJ in app/app.js).
CHAT_INJ = re.compile(r"(ignore (all |your |the |these )*(previous|prior|the above|rules|instructions)|"
                      r"forget (all |your |the )*(rules|instructions)|system prompt|you are now|disregard|"
                      r"set .{0,40}(cost|costs).{0,10}(to )?0|report .* lower|pretend|override (the )?(rules|data)|"
                      r"ignoriere|vergiss (alle|deine)|neue anweisung)", re.I)


def is_injection(q: str) -> bool:
    from .limits import _INJ
    return bool(_INJ.search(q) or CHAT_INJ.search(q))


_NUM = re.compile(r"(?<![\w.\[])(\d{1,3}(?:[,'’]\d{3})+(?:\.\d+)?|\d+(?:\.\d+)?)(?![\w\]])")
_UNIT_AFTER = re.compile(r"^\s*(%|kg|kwh|mwh|t\b|pd|person|chf|gpu|node|vcpu|seats?|licen)", re.I)


def numbers(text: str) -> list[tuple[float, int, int, int]]:
    """(value, decimals, start, end) for every number; [n] citations are not numbers."""
    out = []
    for m in _NUM.finditer(re.sub(r"\[\d+\]", lambda x: " " * len(x.group()), text)):
        raw = re.sub(r"[,'’]", "", m.group(1))
        d = len(raw.split(".")[1]) if "." in raw else 0
        out.append((float(raw), d, m.start(1), m.end(1)))
    return out


def _known(v: float, d: int, pool: list[tuple[float, int]]) -> bool:
    """Known = equal to a fact number, or that number rounded to the answer's decimals (also as a percentage)."""
    return any(abs(p - v) < 1e-9 or round(p, d) == v or round(p * 100, d) == v for p, _ in pool)


def verify_numbers(answer: str, facts: list[dict], question: str = "") -> tuple[str, dict]:
    """Golden rule 1: a figure that is not in the retrieved facts (or the question) is replaced."""
    pool = [(v, d) for f in facts for v, d, *_ in numbers(f["text"])] + [(v, d) for v, d, *_ in numbers(question)]
    found, removed, out, last = [], [], [], 0
    for v, d, s, e in numbers(answer):
        unit = _UNIT_AFTER.match(answer[e:e + 8]) or answer[max(0, s - 4):s].upper().endswith("CHF ")
        if _known(v, d, pool) or (not unit and d == 0 and v <= 12):
            found.append(answer[s:e])
            continue
        removed.append(answer[s:e])
        out.append(answer[last:s] + "[not in the data]")
        last = e
    out.append(answer[last:])
    return "".join(out), {"numbers": len(found) + len(removed), "verified": len(found), "removed": removed}


def cited(answer: str, n_facts: int) -> list[int]:
    return sorted({int(x) for x in re.findall(r"\[(\d+)\]", answer) if 1 <= int(x) <= n_facts})
